      "verse": 4,
      "startVerse": 1,
      "endVerse": 7,
      "author": "Proverbs 16:9",
      "authorHandle": "",
      "text": "\"A man's heart deviseth his way: but the LORD directeth his steps.\" Proverbs 16:9",
      "likes": 0,
      "isLikedByUser": false,
      "isBookmarkedByUser": false,
      "createdAt": "2026-09-23T00:00:00.000Z",
