      "startVerse": 17,
      "endVerse": 20,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "This is what the Earth will face. They will face worldly fear.",
      "likes": 0,
      "isLikedByUser": false,
      "isBookmarkedByUser": false,
      "createdAt": "2026-09-23T00:00:00.000Z",
