          "chapter": 34,
          "verse": 2,
          "startVerse": 1,
          "endVerse": 4,
          "author": "Tried By Fire",
          "authorHandle": "@TriedByFire",
          "text": "Now we have some different characteristics of God.",
          "likes": 0,
          "isLikedByUser": false,
          "isBookmarkedByUser": false,
