          "book": "Isaiah",
          "chapter": 34,
          "verse": 2,
          "startVerse": 1,
          "endVerse": 4,
          "author": "Proverbs 10:14",
          "authorHandle": "",
          "text": "\"Wise men lay up knowledge: but the mouth of the foolish is near destruction.\" Proverbs 10:14",
          "likes": 0,
          "isLikedByUser": false,
          "isBookmarkedByUser": false,
          "createdAt": "2026-09-23T00:00:00.000Z",
